package api

const activationSuccessHTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>激活成功 · Blogo</title>\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{min-height:100vh;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#0f0f1a,#1a1a2e,#16213e);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Helvetica,Arial,sans-serif}\n.card{background:rgba(20,28,38,0.92);border:1px solid rgba(255,255,255,0.06);border-radius:20px;padding:48px 40px;text-align:center;max-width:420px;width:90%;box-shadow:0 8px 40px rgba(0,0,0,0.4)}\n.icon{width:72px;height:72px;border-radius:50%;background:rgba(52,211,153,0.12);display:flex;align-items:center;justify-content:center;margin:0 auto 24px}\n.icon svg{width:36px;height:36px;stroke:#34d399;fill:none;stroke-width:2}\nh1{color:#fff;font-size:22px;font-weight:700;margin-bottom:12px;letter-spacing:-0.02em}\np{color:rgba(255,255,255,0.5);font-size:14px;line-height:1.7;margin-bottom:28px}\na{display:inline-block;padding:12px 32px;background:rgba(99,102,241,0.9);color:#fff;border-radius:10px;text-decoration:none;font-size:14px;font-weight:600;transition:all .25s}\na:hover{background:rgba(129,140,248,0.9);transform:translateY(-1px);box-shadow:0 4px 16px rgba(99,102,241,0.3)}\n</style></head>\n<body>\n<div class=\"card\">\n<div class=\"icon\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n<h1>激活成功</h1>\n<p>你的 Blogo 账号已成功激活。<br>现在可以登录并开始探索。</p>\n<a href=\"/login\">去登录</a>\n</div>\n</body></html>"

func activationFailureHTML(detail string) string {
	if detail == "" {
		detail = "激活链接无效或已过期，请重新注册或联系管理员。"
	}
	return "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>激活失败 · Blogo</title>\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{min-height:100vh;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#0f0f1a,#1a1a2e,#16213e);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Helvetica,Arial,sans-serif}\n.card{background:rgba(20,28,38,0.92);border:1px solid rgba(255,255,255,0.06);border-radius:20px;padding:48px 40px;text-align:center;max-width:420px;width:90%;box-shadow:0 8px 40px rgba(0,0,0,0.4)}\n.icon{width:72px;height:72px;border-radius:50%;background:rgba(248,113,113,0.12);display:flex;align-items:center;justify-content:center;margin:0 auto 24px}\n.icon svg{width:36px;height:36px;stroke:#f87171;fill:none;stroke-width:2}\nh1{color:#fff;font-size:22px;font-weight:700;margin-bottom:12px;letter-spacing:-0.02em}\np{color:rgba(255,255,255,0.45);font-size:14px;line-height:1.7;margin-bottom:28px}\na{display:inline-block;padding:12px 32px;background:rgba(255,255,255,0.08);color:rgba(255,255,255,0.6);border-radius:10px;text-decoration:none;font-size:14px;font-weight:500;transition:all .25s}\na:hover{background:rgba(255,255,255,0.12);color:#fff}\n</style></head>\n<body>\n<div class=\"card\">\n<div class=\"icon\"><svg viewBox=\"0 0 24 24\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg></div>\n<h1>激活失败</h1>\n<p>" + detail + "</p>\n<a href=\"/register\">重新注册</a>\n</div>\n</body></html>"
}
